bool Editor::shortcutGestureBusy(const std::string& id)const{
 // A stationary gradient is a pending IO decision. The existing resolver must
 // receive it; only a live drag/capture should keep that decision queued.
 if(gradientPending_&&gradientIoCommand(id))return currentDocument().strokeActive()||hasCapture()||selectionDragging_||floatingDragging_||shapeDragging_||gradientDragging_||fillDragging_||navigation_.zoomDragging_;
 return historyGestureBusy();
}
void Editor::dispatchShortcutAction(const std::string& id){
 if(documentOpen_&&!homeOpen_&&(id=="undo"||id=="redo")){
  requestHistoryAction(id=="undo"?workspace::HistoryAction::Undo:workspace::HistoryAction::Redo);return;
 }
 if(documentOpen_&&shortcutGestureBusy(id)){
  deferredShortcuts_.push_back({currentDocument().identity(),id});shortcutDeferredTimer_.start();return;
 }
 runShortcutCommand(id);
}
