if(focus&&focus->window()!=window())return 2;
if(key->scancode()==ui::kKeyEnter&&(gradientDragging_||gradientPending_||selectionDragging_||floatingDragging_||shapeDragging_||currentDocument().selection()||dynamic_cast<ui::Button*>(focus)))return 0;
